#include <stdio.h>

#include <stdint.h>

#define width_msk(width) ((uint32_t)(((uint32_t)0xffffffff) >> (32 - width)))
#define fld_msk( bit, width ) (width_msk(width) << bit)

/* block   : interrupts0
   register: setintenable0
   field   : setinten0
   access  : read-write

Fifoctrl Ch#0 RX sync Interrupt set. When a 1 is writen to the this
bit the corresponding interrupt is enabled; when a zero is written to
this bit there is no change in the interrupt enable state. Reading
either the 'set' or 'clr' address for this register returns the
current state on the interrupt enable.
*/
uint32_t get_fld_interrupts0__setintenable0__setinten0( uint32_t *reg_val )
{
    return( ((*reg_val) >> 0) & width_msk( 1 ));
}

uint32_t set_fld_interrupts0__setintenable0__setinten0( uint32_t *reg_val, uint32_t fld_val )
{
    *reg_val= ( ((*reg_val) & ~fld_msk( 0, 1 )) |
                ((fld_val & width_msk( 1 )) << 0) );
    return *reg_val;
}

